"""Directed n-cycle collapse: the blend-coloring space is 1-dimensional."""
from __future__ import annotations
from typing import List

def directed_cycle(n: int) -> List[List[float]]:
    return [[1.0 if j == (i + 1) % n else 0.0 for j in range(n)] for i in range(n)]

def kernel_dimension(W: List[List[float]], tol: float = 1e-9) -> int:
    n = len(W)
    L = [[(1.0 if i == j else 0.0) - W[i][j] for j in range(n)] for i in range(n)]
    rank, r, col = 0, 0, 0
    while r < n and col < n:
        p = max(range(r, n), key=lambda k: abs(L[k][col]))
        if abs(L[p][col]) <= tol:
            col += 1; continue
        L[r], L[p] = L[p], L[r]
        pv = L[r][col]; L[r] = [x / pv for x in L[r]]
        for k in range(n):
            if k != r and abs(L[k][col]) > tol:
                f = L[k][col]; L[k] = [a - f * b for a, b in zip(L[k], L[r])]
        r += 1; rank += 1; col += 1
    return n - rank

if __name__ == "__main__":
    for n in range(2, 12):
        print(f"n={n:2d}  blend-coloring dimension = {kernel_dimension(directed_cycle(n))}")

"""Sharpness: dropping strong connectivity yields non-constant blend colorings."""
from __future__ import annotations
from typing import List

def blend_step(W: List[List[float]], c: List[float]) -> List[float]:
    n = len(W)
    return [sum(W[i][j] * c[j] for j in range(n)) for i in range(n)]

def reachable(W, s, tol=1e-12):
    n = len(W); seen = {s}; stack = [s]
    while stack:
        i = stack.pop()
        for j in range(n):
            if W[i][j] > tol and j not in seen:
                seen.add(j); stack.append(j)
    return seen

if __name__ == "__main__":
    W = [[1.0, 0.0], [0.0, 1.0]]           # two disjoint self-loops
    sc = all(len(reachable(W, i)) == len(W) for i in range(len(W)))
    c = [0.0, 1.0]
    print("strongly connected:", sc)        # False
    print("c = (0,1) is a fixed point:", blend_step(W, c) == c)  # True -> non-constant blend

"""Averaging dynamics on a strongly connected chain converge to consensus."""
from __future__ import annotations
import random
from typing import List

def random_strongly_connected(n: int, seed: int = 0) -> List[List[float]]:
    rng = random.Random(seed)
    W = [[0.0] * n for _ in range(n)]
    for i in range(n):
        W[i][(i + 1) % n] += 1.0
        for j in range(n):
            W[i][j] += rng.random()
        s = sum(W[i]); W[i] = [x / s for x in W[i]]
    return W

def step(W, c):
    n = len(W); return [sum(W[i][j] * c[j] for j in range(n)) for i in range(n)]

if __name__ == "__main__":
    n = 8; W = random_strongly_connected(n, seed=1)
    c = [float(i) for i in range(n)]
    for t in range(0, 41, 10):
        print(f"t={t:2d}  spread = {max(c) - min(c):.3e}")
        for _ in range(10): c = step(W, c)
    print("final coloring:", [round(x, 6) for x in c])

